                for j in range(26):
                    if reach[k][j]:
                        reach[i][j] = True

    comp = [find(i) for i in range(26)]

    # unit nodes
    left = []   # negative vertices (with multiplicity)
    right = []  # positive vertices (with multiplicity)
    for v in range(26):
        if not used[v]:
            continue
        if d[v] < 0:
            left.extend([v] * (-d[v]))
        elif d[v] > 0:
            right.extend([v] * d[v])

    adj = [[] for _ in range(len(left))]
    for i, v in enumerate(left):
